css:
.loader {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #6366f1;
  box-shadow: inset 0 0 0 4px #4338ca;
  animation: flip 1s ease-in-out infinite;
}
@keyframes flip {
  0%, 100% { transform: scaleX(1); background: #6366f1; }
  25% { transform: scaleX(0.1); }
  26% { background: #a5b4fc; }
  50% { transform: scaleX(1); background: #a5b4fc; }
  75% { transform: scaleX(0.1); }
  76% { background: #6366f1; }
}
